import{fetchProducts}from'./dataFetcher.min.js';import{renderGrid,setupUI}from'./ui.min.js';const yearEl=document.getElementById('year');if(yearEl)yearEl.textContent=new Date().getFullYear();setupUI();(async function load(){try{const products=await fetchProducts('/final/assets/data/products.json');const featured=products.slice(0,6);const featuredList=document.getElementById('featured-list');if(featuredList)renderGrid(featuredList,featured);const productsGrid=document.getElementById('products-grid');if(productsGrid)renderGrid(productsGrid,products,{showFav:!0})}catch(err){console.error('Failed to load products',err);const msg=document.createElement('p');msg.textContent='Sorry — we could not load the products at this time.';document.querySelector('.container').appendChild(msg)}})();